DO $$ BEGIN
 IF NOT (SELECT relrowsecurity FROM pg_class WHERE oid='public.sales_qbo_sandbox_oauth_states'::regclass) OR has_table_privilege('anon','public.sales_qbo_sandbox_oauth_states','SELECT') OR has_table_privilege('authenticated','public.sales_qbo_sandbox_oauth_states','SELECT') THEN RAISE EXCEPTION 'SANDBOX_STATE_ACCESS_INVALID'; END IF;
