 IF has_function_privilege('anon','public.native_sales_qbo_sandbox_claim_refresh(uuid,uuid)','EXECUTE') OR has_function_privilege('authenticated','public.native_sales_qbo_sandbox_claim_refresh(uuid,uuid)','EXECUTE') OR NOT has_function_privilege('service_role','public.native_sales_qbo_sandbox_claim_refresh(uuid,uuid)','EXECUTE') THEN RAISE EXCEPTION 'SANDBOX_RPC_ACCESS_INVALID'; END IF;
 IF has_function_privilege('anon','public.native_sales_qbo_sandbox_finish_refresh(uuid,uuid,text,text,timestamptz,timestamptz)','EXECUTE') OR has_function_privilege('authenticated','public.native_sales_qbo_sandbox_finish_refresh(uuid,uuid,text,text,timestamptz,timestamptz)','EXECUTE') OR NOT has_function_privilege('service_role','public.native_sales_qbo_sandbox_finish_refresh(uuid,uuid,text,text,timestamptz,timestamptz)','EXECUTE') THEN RAISE EXCEPTION 'SANDBOX_RPC_ACCESS_INVALID'; END IF;
 IF has_function_privilege('anon','public.native_sales_qbo_sandbox_hold_for_revocation(uuid,uuid)','EXECUTE') OR has_function_privilege('authenticated','public.native_sales_qbo_sandbox_hold_for_revocation(uuid,uuid)','EXECUTE') OR NOT has_function_privilege('service_role','public.native_sales_qbo_sandbox_hold_for_revocation(uuid,uuid)','EXECUTE') THEN RAISE EXCEPTION 'SANDBOX_RPC_ACCESS_INVALID'; END IF;
 IF has_function_privilege('anon','public.native_sales_qbo_sandbox_disconnect(uuid,uuid)','EXECUTE') OR has_function_privilege('authenticated','public.native_sales_qbo_sandbox_disconnect(uuid,uuid)','EXECUTE') OR NOT has_function_privilege('service_role','public.native_sales_qbo_sandbox_disconnect(uuid,uuid)','EXECUTE') THEN RAISE EXCEPTION 'SANDBOX_RPC_ACCESS_INVALID'; END IF;
END $$;
